byte[] latin1 = "Café Müller".getBytes(StandardCharsets.ISO_8859_1);  // é is 0xE9
byte[] utf8 = "Café Müller".getBytes(StandardCharsets.UTF_8);         // é is 0xC3 0xA9
Path latin1File = Files.write(Path.of("out", "latin1.txt"), latin1);

